script:
(function () {
  'use strict';
  // How each payment of a fixed-rate loan splits into interest and principal.
  //   Periodic rate i = annual rate / f, n = years x f, payment P = L x i / (1 - (1 + i)^-n) (L / n at 0%).
  //   Principal in payment k = (P - L i)(1 + i)^(k-1); interest = P - principal.
  //   Crossover (first payment with principal >= interest): smallest k with
  //   (P - L i)(1 + i)^(k-1) >= P / 2, i.e. k = ceil(1 + ln(P / (2(P - L i))) / ln(1 + i)), or 1 if L i <= P / 2.
  //   The crossover shown comes from the payment-by-payment schedule; crossover() is the closed form it is tested against.
  //   Half repaid: first payment after which the balance is at most L / 2.
  // Checked in Node (scratchpad tests/w3b6_loans/clp.test.js): $300,000 at 6.5% over 30 years ->
  //   $1,896.20 a month, first payment $1,625.00 interest / $271.20 principal (85.7% interest), total
  //   interest $382,633.47 (= 360 x P - L); the closed-form crossover (payment 233, year 20) and principal of
  //   payment 120 match a payment-by-payment simulation; half the loan repaid at payment 257 (checked by an independent loop); 0% rate
  //   gives all principal and a crossover at payment 1; yearly interest + principal = yearly payments.
  var money = new Intl.NumberFormat('en-US', { style: 'currency', currency: 'USD', minimumFractionDigits: 2, maximumFractionDigits: 2 });
  var PER = { 52: 'week', 26: 'two weeks', 24: 'half-month', 12: 'month', 4: 'quarter', 1: 'year' };

  function el(id) { return document.getElementById(id); }
  function setText(id, t) { el(id).textContent = t; }
  function read(id) {
    var raw = String(el(id).value).trim();
    if (raw === '') return NaN;
    var v = Number(raw);
    return isFinite(v) ? v : NaN;
  }
  function pct(x) { return (Math.round(x * 1000) / 10).toFixed(1) + '%'; }

  function payment(loan, i, n) { return i === 0 ? loan / n : loan * i / (1 - Math.pow(1 + i, -n)); }

  function crossover(loan, i, pay) {
    if (loan * i <= pay / 2) return 1;
    return Math.ceil(1 + Math.log(pay / (2 * (pay - loan * i))) / Math.log(1 + i) - 1e-9);
  }

  function build(loan, rate, years, f) {
    var i = rate / f, n = years * f, pay = payment(loan, i, n), bal = loan, rows = [], years_ = [], half = 0, total = 0, y = null, cross = 0;
    for (var k = 1; k <= n; k++) {
      var interest = bal * i, principal = k === n ? bal : pay - interest, amount = interest + principal;
      bal -= principal;
      if (k === n || Math.abs(bal) < 1e-7) bal = 0;
      total += interest;
      if (!cross && principal >= interest - 1e-9) cross = k;
      if (!half && bal <= loan / 2 + 1e-7) half = k;
      rows.push({ k: k, interest: interest, principal: principal, payment: amount, balance: bal });
      var yr = Math.ceil(k / f);
      if (!y || y.year !== yr) { y = { year: yr, paid: 0, interest: 0, principal: 0, balance: 0 }; years_.push(y); }
      y.paid += amount; y.interest += interest; y.principal += principal; y.balance = bal;
    }
    return { payment: pay, n: n, rows: rows, years: years_, interest: total, cross: cross, half: half };
  }

  function when(k, f) {
    var yr = Math.ceil(k / f);
    return 'payment ' + k + ' (year ' + yr + ')';
  }
  function bar(share) {
    var w = Math.max(0, Math.min(100, share * 100)).toFixed(1);
    return '<div class="flex items-center gap-2"><div class="usage-bar w-24 shrink-0"><div class="usage-bar-fill" style="--usage-value: ' + w + '%"></div></div><span>' + pct(share) + '</span></div>';
  }

  function clear() {
    ['clpCross', 'clpFirstShare', 'clpHalf', 'clpTotalShare', 'clpSummary'].forEach(function (id) { setText(id, '–'); });
    el('clpPicks').innerHTML = ''; el('clpByYear').innerHTML = '';
  }

  function update() {
    var loan = read('clpLoan'), rate = read('clpRate'), years = read('clpYears'), f = parseInt(el('clpFreq').value, 10), pick = read('clpPick');
    var err = el('clpError'), msg = '';
    if ([loan, rate, years].some(isNaN)) msg = 'Enter the loan amount, interest rate and term.';
    else if (loan <= 0 || loan > 1e10) msg = 'Enter a loan amount above $0.';
    else if (rate < 0 || rate > 50) msg = 'Enter an interest rate from 0% to 50%.';
    else if (years < 1 || years > 40 || years % 1 !== 0) msg = 'Enter a term of 1 to 40 whole years.';
    else if (!PER[f]) msg = 'Choose a payment frequency.';
    else if (String(el('clpPick').value).trim() !== '' && (isNaN(pick) || pick < 1 || pick % 1 !== 0))
      msg = 'Enter a whole payment number of 1 or more to look inside it, or leave it blank.';
    err.hidden = !msg;
    err.textContent = msg;
    if (msg) { clear(); return; }

    var r = build(loan, rate / 100, years, f), first = r.rows[0];
    var paidTotal = loan + r.interest;
    setText('clpCross', rate === 0 ? 'Payment 1' : 'Payment ' + r.cross);
    setText('clpFirstShare', pct(first.interest / first.payment));
    setText('clpHalf', 'Payment ' + r.half);
    setText('clpTotalShare', pct(paidTotal > 0 ? r.interest / paidTotal : 0));
    var s = 'Each ' + PER[f] + ' you pay ' + money.format(r.payment) + '. ';
    if (rate === 0) s += 'With no interest, every dollar goes to principal.';
    else {
      s += 'The first payment puts ' + money.format(first.interest) + ' toward interest and ' + money.format(first.principal) + ' toward principal. ';
      if (r.cross === 1) s += 'Principal is the bigger part from the very first payment.';
      else s += 'Principal becomes the bigger part at ' + when(r.cross, f) + ', ' + Math.round(r.cross / r.n * 100) + '% of the way through the loan.';
      s += ' Half the loan is repaid by ' + when(r.half, f) + '. Over the whole loan you pay ' + money.format(r.interest) + ' in interest.';
    }
    setText('clpSummary', s);

    var picks = [{ label: 'First', k: 1 }];
    if (rate > 0 && r.cross > 1) picks.push({ label: 'Crossover', k: r.cross });
    if (!isNaN(pick) && pick <= r.n && pick !== 1 && pick !== r.n && pick !== r.cross) picks.push({ label: 'Your pick', k: pick });
    picks.push({ label: 'Last', k: r.n });
    picks.sort(function (a, b) { return a.k - b.k; });
    el('clpPicks').innerHTML = picks.map(function (p) {
      var row = r.rows[p.k - 1], share = row.payment > 0 ? row.interest / row.payment : 0;
      return '<tr><th scope="row">' + p.label + ': #' + p.k + '</th><td>' + money.format(row.interest) + '</td><td>' + money.format(row.principal) +
        '</td><td>' + pct(share) + '</td><td>' + money.format(row.balance) + '</td></tr>';
    }).join('');
    el('clpByYear').innerHTML = r.years.map(function (y) {
      var share = y.paid > 0 ? y.interest / y.paid : 0;
      return '<tr><td>' + y.year + '</td><td>' + money.format(y.paid) + '</td><td>' + money.format(y.interest) + '</td><td>' + money.format(y.principal) +
        '</td><td>' + bar(share) + '</td><td>' + money.format(y.balance) + '</td></tr>';
    }).join('');
  }

  document.addEventListener('DOMContentLoaded', function () {
    var form = el('clpForm');
    form.addEventListener('input', update);
    form.addEventListener('change', update);
    form.addEventListener('submit', function (e) { e.preventDefault(); });
    update();
  });
})();
